{
  "@context": "https://schema.org",
  "@type": "WebApplication",
  "name": "Kalkulator Biaya Kecelakaan Kerja & ROI K3",
  "url": "https://wahanatotalita.com/tools/kalkulator-biaya-k3/",
  "description": "Kalkulator analisis biaya kecelakaan kerja langsung vs tersembunyi menggunakan teori gunung es Heinrich dan Frank Bird beserta estimasi ROI pencegahan K3.",
  "applicationCategory": "BusinessApplication",
  "operatingSystem": "All",
  "offers": { "@type": "Offer", "price": "0", "priceCurrency": "IDR" }
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Apa itu Teori Gunung Es (Iceberg Theory) dalam biaya kecelakaan K3?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Teori Gunung Es mengilustrasikan bahwa biaya langsung kecelakaan (biaya medis dan klaim asuransi) hanyalah puncak gunung es yang terlihat di atas permukaan laut. Bagian terbesar dari kerugian finansial perusahaan (biaya tersembunyi/tak langsung) berada di bawah permukaan laut dengan nilai 4 hingga 10 kali lipat lebih besar, seperti terhentinya lini produksi, jam kerja investigasi, denda regulasi, dan hilangnya reputasi bisnis."
      }
    },
    {
      "@type": "Question",
      "name": "Berapa rasio perbandingan biaya langsung dan tidak langsung menurut Heinrich dan Frank Bird?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "H.W. Heinrich (1931) menetapkan rasio biaya langsung dibanding biaya tidak langsung adalah 1 : 4. Sedangkan penelitian lanjutan oleh Frank E. Bird Jr. (1969) dan studi modern menunjukkan rasio kerugian terselubung bisa mencapai 1 : 10 hingga 1 : 50 tergantung jenis industri dan dampak terhadap aset operasional."
      }
    },
    {
      "@type": "Question",
      "name": "Bagaimana cara meyakinkan manajemen puncak (C-Level) untuk berinvestasi dalam program K3?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Gunakan kalkulasi Return on Investment (ROI) K3: tunjukkan bahwa setiap Rp 1 yang diinvestasikan pada pencegahan keselamatan kerja rata-rata menghemat Rp 4 hingga Rp 6 dari potensi kerugian kecelakaan kerja tersembunyi yang dapat mengancam kelangsungan arus kas perusahaan."
      }
    }
  ]
}

inline_styles:
:root {
  --navy-dark: #071524;
  --navy: #0D233A;
  --navy-light: #183654;
  --orange: #E8611A;
  --orange-hover: #cf5213;
  --orange-light: #fff2ea;
  --slate-50: #F8FAFC;
  --slate-100: #F1F5F9;
  --slate-200: #E2E8F0;
  --slate-300: #CBD5E1;
  --slate-600: #475569;
  --slate-700: #334155;
  --slate-900: #0F172A;
  --radius-md: 12px;
  --radius-lg: 16px;
  --shadow-sm: 0 2px 8px rgba(13,35,58,0.06);
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Source Sans 3', system-ui, -apple-system, sans-serif;
  background: var(--slate-50);
  color: var(--slate-900);
  line-height: 1.6;
}
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

/* HERO */
.cost-hero {
  background: linear-gradient(135deg, #071524 0%, #0D233A 60%, #183654 100%);
  color: #fff;
  padding: 58px 0 44px;
  position: relative;
  overflow: hidden;
  border-bottom: 3px solid var(--orange);
}
.cost-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
  background-size: 36px 36px;
  pointer-events: none;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(232, 97, 26, 0.18);
  border: 1px solid rgba(232, 97, 26, 0.4);
  padding: 6px 14px;
  border-radius: 999px;
  color: #FFA573;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 14px;
}
.cost-hero h1 {
  font-family: 'Lexend', sans-serif;
  font-size: clamp(1.8rem, 3.6vw, 2.7rem);
  font-weight: 800;
  line-height: 1.2;
  margin-bottom: 12px;
}
.cost-hero h1 span { color: var(--orange); }
.cost-hero p {
  color: #CBD5E1;
  font-size: 1.05rem;
  max-width: 760px;
  margin-bottom: 20px;
}
.hero-tags { display: flex; flex-wrap: wrap; gap: 8px; }
.hero-tag {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  padding: 4px 12px;
  border-radius: 6px;
  font-size: 0.82rem;
  color: #E2E8F0;
}

/* WORKSPACE LAYOUT */
.cost-wrapper { padding: 40px 0 60px; }
.cost-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 32px;
  align-items: start;
}
@media (max-width: 992px) {
  .cost-grid { grid-template-columns: 1fr; }
}

.card-box {
  background: #fff;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
  padding: 28px;
  margin-bottom: 28px;
}
.card-header-line {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 2px solid var(--slate-100);
  padding-bottom: 16px;
  margin-bottom: 22px;
}
.card-title {
  font-family: 'Lexend', sans-serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--navy);
  display: flex;
  align-items: center;
  gap: 10px;
}

/* FORM FIELDS */
.form-field { margin-bottom: 16px; }
.form-label {
  display: flex;
  justify-content: space-between;
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 6px;
}
.form-label small { color: var(--slate-600); font-weight: 400; }
.form-input {
  width: 100%;
  padding: 10px 14px;
  border: 1.5px solid var(--slate-200);
  border-radius: var(--radius-md);
  font-size: 0.95rem;
  color: var(--slate-900);
  background: #fff;
}
.form-input:focus { outline: none; border-color: var(--orange); }

.ratio-toggle {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  background: var(--slate-100);
  padding: 6px;
  border-radius: var(--radius-md);
  margin-bottom: 20px;
}
.ratio-btn {
  padding: 10px;
  border: none;
  background: transparent;
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--slate-700);
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s;
  text-align: center;
}
.ratio-btn.active {
  background: #fff;
  color: var(--navy);
  box-shadow: 0 2px 6px rgba(0,0,0,0.08);
}

/* ICEBERG VISUAL BOX */
.iceberg-box {
  background: linear-gradient(180deg, #E0F2FE 0%, #BAE6FD 30%, #0284C7 60%, #0369A1 100%);
  border-radius: var(--radius-lg);
  padding: 24px;
  color: #fff;
  position: relative;
  overflow: hidden;
  margin-bottom: 24px;
  text-shadow: 0 1px 2px rgba(0,0,0,0.2);
}
.ice-surface-line {
  border-bottom: 2px dashed rgba(255,255,255,0.7);
  padding-bottom: 12px;
  margin-bottom: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.ice-top {
  background: rgba(255,255,255,0.9);
  color: var(--navy);
  padding: 14px;
  border-radius: 8px;
  margin-bottom: 16px;
  font-weight: 600;
  font-size: 0.9rem;
  text-shadow: none;
}
.ice-bottom {
  background: rgba(3, 105, 161, 0.7);
  border: 1px solid rgba(255,255,255,0.2);
  padding: 16px;
  border-radius: 8px;
  font-size: 0.88rem;
  line-height: 1.6;
}

/* RESULTS */
.stat-card {
  background: var(--slate-50);
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  padding: 18px;
  margin-bottom: 14px;
}
.stat-card.featured {
  background: linear-gradient(145deg, #0D233A 0%, #183654 100%);
  color: #fff;
  border-color: #0D233A;
}
.stat-card.featured .stat-meta { color: #FFA573; }
.stat-card.featured .stat-val { color: #fff; }
.stat-card.featured .stat-desc { color: #CBD5E1; }
.stat-meta {
  font-size: 0.76rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--slate-600);
  margin-bottom: 4px;
}
.stat-val {
  font-family: 'Lexend', sans-serif;
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--navy);
  line-height: 1.2;
  margin-bottom: 4px;
}
.stat-desc { font-size: 0.8rem; color: var(--slate-600); }

/* EDITORIAL ARTICLE */
.editorial-box {
  background: #fff;
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-lg);
  padding: 36px;
  margin-bottom: 32px;
}
.editorial-title {
  font-family: 'Lexend', sans-serif;
  font-size: 1.45rem;
  font-weight: 800;
  color: var(--navy);
  margin-bottom: 16px;
  border-left: 4px solid var(--orange);
  padding-left: 14px;
}
.editorial-p {
  color: var(--slate-700);
  font-size: 0.96rem;
  line-height: 1.7;
  margin-bottom: 16px;
}

/* FAQ */
.faq-item {
  border: 1px solid var(--slate-200);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
  background: #fff;
}
.faq-q {
  width: 100%;
  padding: 16px 20px;
  text-align: left;
  background: #fff;
  border: none;
  font-family: 'Lexend', sans-serif;
  font-size: 0.98rem;
  font-weight: 700;
  color: var(--navy);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-q:hover { background: var(--slate-50); }
.faq-a {
  padding: 0 20px 18px;
  color: var(--slate-700);
  font-size: 0.92rem;
  line-height: 1.65;
  display: none;
}
.faq-item.active .faq-a { display: block; }
.faq-item.active .faq-icon { transform: rotate(180deg); }
.faq-icon { transition: transform 0.2s; }

